class Solution {
public:
    vector<int> smallerNumbersThanCurrent(vector<int>& nums) {
        int count[101] = {0};
        for (int x : nums) count[x]++;
        int prefix[101];
        prefix[0] = 0;
        for (int v = 1; v <= 100; v++) {
            prefix[v] = prefix[v - 1] + count[v - 1];
        }
        vector<int> ans(nums.size());
        for (int i = 0; i < (int)nums.size(); i++) {
            ans[i] = prefix[nums[i]];
        }
        return ans;
    }
};
